export const meta = {
  name: 'mm03-p7-verify',
  description: 'Second verification of pass-7 review fixes and of every factual claim in the French report',
  phases: [{ title: 'Check' }, { title: 'Judge' }],
}

const CTX = `
Context (read-only review; do NOT edit any repo file, do NOT run lake build):
- Repo /Users/guygouri/Devlab/ernlang/ern, branch formal/access_model_0.1. Lean 4 core, no Mathlib. Module formal/Ern/MM03.lean (already built at HEAD 6615edd; the olean is current).
- Report under check (French, uncommitted): formal/reports/MM03_v0.1_p7.md. Previous report: formal/reports/MM03_v0.1_p6.md. Old module (end of pass 6, commit 1e8325b): /private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/p7/mm03_p6.lean.
- Task brief with arbitrages G1-G5 (French): /private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/task_mm03_p7.md. Spec: /Users/guygouri/Downloads/ERN_Memory_Model_0.3.3.md.
- For Lean checks write files in your own folder /private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/p7ver_<yourlabel>/ starting with "import Ern.MM03" and "open Ern.MM03"; run: cd /Users/guygouri/Devlab/ernlang/ern/formal && ~/.elan/bin/lake env lean <file>. Concrete states are checked with decide (e.g. "example : X := by decide", "#eval decide (P)").
- Statement differ: python3 /private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/stmts.py <old> <new>.
- Commits of the pass: git -C /Users/guygouri/Devlab/ernlang/ern log --oneline 1e8325b..HEAD.
A finding is a claim of the report (or a property of the fixes) that is false, unsupported by any module declaration, or imprecise in a way that matters. Every finding needs evidence: a quote of the report line, the module text, a compiling Lean check with its output, or command output. No evidence, no finding. Do not ask for additions beyond the task. Do not report style or French wording issues.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          where: { type: 'string', description: 'report section and quoted words, or module declaration' },
          claim: { type: 'string' },
          problem: { type: 'string' },
          evidence: { type: 'string' },
          fix: { type: 'string', description: 'proposed correction' },
          severity: { type: 'string', enum: ['major', 'minor'] },
        },
        required: ['where', 'claim', 'problem', 'evidence', 'fix', 'severity'],
      },
    },
    checked: { type: 'string', description: 'short list of what was checked and found correct' },
  },
  required: ['findings', 'checked'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean' },
    reason: { type: 'string' },
    evidence: { type: 'string' },
    fix: { type: 'string' },
  },
  required: ['real', 'reason', 'evidence', 'fix'],
}

const TASKS = [
  { key: 'fixes', prompt: `Review commit 6615edd ("review fixes") of formal/Ern/MM03.lean: git -C /Users/guygouri/Devlab/ernlang/ern show 6615edd -- formal/Ern/MM03.lean. Check: (1) EnterPreBase is textually the pass-6 EnterPre (compare with the old module) and EnterPre = EnterPreBase ∧ G1 ∧ G4 says what G1 and G4 require; (2) IssueStatic is back to its pass-6 text, IssueStep.ok now requires AnchorOrderHeld of the arrival state and the new noAnchor rejection is the only new outcome: confirm that no pass-6 or pass-7 verdict changes except as the report says (an issue on an unavailable region gives fail as in pass 6), and that issue_det still holds meaning; (3) every new witness theorem (call_protects_params_safe_fails_unblock_active, _fails_exit, _fails_exit_strict, f7a_cycle_by_release, eu5_reachable, cycle_by_release, cycle_by_endUse, cycle_by_free, cycle_by_exit, enter_helper_rejected, noOrphanEff_fails, transfer_inits_unwritten, transfer_inits_unwritten_after_store, issue_inits_unwritten, callee_issue_unavailable_fails) states what its docstring says, no more and no less; (4) no theorem statement was weakened by the fix (run the statement differ old vs new). Run #print axioms on the new theorems.` },
  { key: 'head', prompt: `Fact-check the beginning of the report formal/reports/MM03_v0.1_p7.md: the header, "État de la vérification" (counts: run grep -c '^theorem ' and '^example' on the module, and an axiom sweep: generate a Lean file with "#print axioms <name>" for every theorem name and count the outputs by axiom set; check the claim 471/99/9 and 579 theorems, 364 examples, 369 in pass 6 with 5 removed), "Résultats principaux", "Commits" (hashes and contents vs git log), and "Corrections après la revue adverse" (each row: the named declarations exist and say what the row says). Verify that git diff 1e8325b -- formal/Ern/MM02.lean is empty.` },
  { key: 'acd', prompt: `Fact-check sections (a) to (f) of the report formal/reports/MM03_v0.1_p7.md: every declaration named exists in formal/Ern/MM03.lean and plays the role stated; every decision in (c) describes the module accurately (open the definitions: ParamOriginHidden, EnterPre, EnterPreBase, StorePre, storeEff, CoversHolder, NoOrphan, RootLive, AnchorOrderHeld, IssueStep, reachable_access_invariant_ext, store_escape_rejected_at_transfer, anchor_escape_rejected_at_transfer, alloc_preserves_anchorOrderHeld, enter_root_fp_ge, exists_mem_footprint); every claim in (d) and (e) is backed by a module witness as cited (check the cited theorems' statements). Flag any claim without a witness.` },
  { key: 'gq', prompt: `Fact-check sections (g) to (q) of the report formal/reports/MM03_v0.1_p7.md: the verdict table (g) (for each row, the cited theorem exists and proves the stated verdicts; check states and verdicts with decide where useful), the hypotheses table (h) against the actual theorem signatures, the statement-diff section (i) (run the statement differ between the old module and the new one; check counts 484/579, 467 same, 16 changed, 1 removed, and the reasons), (j) to (o), the verdict changes (p) (old vs new examples; claim that no pass-6 rejection became accepted and no fail became reject), and (q) (each witness described says what its theorem proves; in particular which witnesses include NoOrphan and NothingAtFrame0, and the description of the three F6 mechanisms).` },
]

phase('Check')
const results = await pipeline(
  TASKS,
  t => agent(`${CTX}\n\nYour task (${t.key}):\n${t.prompt}\n\nReturn the findings (possibly empty) and what you checked.`, { label: `check:${t.key}`, phase: 'Check', schema: FINDINGS }),
  (r, t) => r ? parallel(r.findings.map((f, i) => () =>
    agent(`${CTX}\n\nA checker reported the following finding about the pass-7 report or module. Try hard to REFUTE it: re-check the evidence yourself (open the report, the module, run the Lean check). If the finding is wrong, unsupported, or only about wording, answer real=false. If it is right, answer real=true and give the most precise fix.\n\nWhere: ${f.where}\nClaim: ${f.claim}\nProblem: ${f.problem}\nEvidence given: ${f.evidence}\nProposed fix: ${f.fix}\nSeverity: ${f.severity}`,
      { label: `judge:${t.key}:${i}`, phase: 'Judge', schema: VERDICT })
      .then(v => ({ task: t.key, ...f, verdict: v })))).then(js => ({ task: t.key, checked: r.checked, judged: js.filter(Boolean) })) : null,
)
const ok = results.filter(Boolean)
const confirmed = ok.flatMap(r => r.judged.filter(j => j.verdict && j.verdict.real))
const refuted = ok.flatMap(r => r.judged.filter(j => !j.verdict || !j.verdict.real))
log(`${confirmed.length} confirmed, ${refuted.length} refuted`)
return { confirmed, refuted: refuted.map(j => ({ task: j.task, where: j.where, problem: j.problem, reason: j.verdict ? j.verdict.reason : 'no verdict' })), checked: ok.map(r => ({ task: r.task, checked: r.checked })) }

