export const meta = {
  name: 'mm03-p8-report-verify',
  description: 'Check each claim of the pass-8 report against the Lean module and the brief, then refute findings',
  phases: [{ title: 'Check' }, { title: 'Judge' }],
}
const SP = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad'
const COMMON = `Repository: /Users/guygouri/Devlab/ernlang/ern (Lake project in formal/). Module: formal/Ern/MM03.lean (uncommitted additions at the end are part of the work). Report under check: formal/reports/MM03_v0.1_p8.md (French). Brief (French, authoritative for this task): ${SP}/task_mm03_p8.md. Pass-7 module snapshot: ${SP}/p8/mm03_p7.lean. Pass-7 report: formal/reports/MM03_v0.1_p7.md. Toolchain: ~/.elan/bin/lake; to check a Lean fact write a scratch file under ${SP}/p8ver/ starting with "import Ern.MM03" and "namespace Ern.MM03", then run "cd formal && ~/.elan/bin/lake env lean <file>". Do NOT edit files under formal/. Read-only review.
Your job: find statements in your assigned report sections that are false, stronger than what the module proves, or missing something the brief requires. Every finding needs evidence: a line of the module, a quoted passage, or command output. No evidence, no finding. Do not report style or wording preferences; only factual errors, overclaims, wrong names/numbers, missing required content. Report at most 12 findings, most severe first.`
const SCHEMA = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: {
  section: { type: 'string' }, claim: { type: 'string' }, problem: { type: 'string' }, evidence: { type: 'string' }, fix: { type: 'string' }, severity: { type: 'string', enum: ['major', 'minor'] } },
  required: ['section', 'claim', 'problem', 'evidence', 'fix', 'severity'] } } }, required: ['findings'] }
const VERDICTS = { type: 'object', properties: { verdicts: { type: 'array', items: { type: 'object', properties: {
  index: { type: 'number' }, real: { type: 'boolean' }, reason: { type: 'string' }, evidence: { type: 'string' } }, required: ['index', 'real', 'reason', 'evidence'] } } }, required: ['verdicts'] }
const PARTS = [
  { key: 'head', text: 'Sections: header, "État de la vérification", "Résultats principaux", "Commits", "Corrections après la revue adverse", (a), (b), (c). Check every count (theorems 605, examples 358, axiom breakdown: rerun the axiom sweep with "sh ' + SP + '/p3/axsweep.sh ' + SP + '/p8ver" and read ' + SP + '/p8ver/ax_out.txt), every commit hash (git log), every declaration name cited, and that each (c) decision describes the definition as written in the module (kids, posIn, corrF, corr, SameShape, mvTo, transferEff, IssueStatic, issueEff, resetEff, LeavesInit, NewArenaPre, Step, WrittenBy, init_only_by_writes, init_statics). The review journal of the adversarial review is in ~/.claude/projects/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/subagents/workflows/wf_279812dc-137/journal.jsonl; check the review table against it.' },
  { key: 'cases', text: 'Sections (d), (e), (g), (h), (i). For each case row of (g), check the stated verdicts against the theorem statements in the module (search the theorem name). For (h), check each hypothesis list against the theorem signatures. For (i), rerun the statement diff: "python3 ' + SP + '/stmts.py ' + SP + '/p8/mm03_p7.lean formal/Ern/MM03.lean" and compare with the counts and lists. For (e), check that each question quotes the witnesses correctly (transfer_shape_ordered, issue_into_arena_value, pf0).' },
  { key: 'verdicts', text: 'Sections (j), (k), (l), (m), (n), (o), (p). For (p), recompute the example diff with "python3 ' + SP + '/p8fix/exdiff.py ' + SP + '/p8/mm03_p7.lean formal/Ern/MM03.lean" and check the removed (22) and added (16) lists item by item, and that every row of the verdict table is backed by a statement in the module. Check the claims of (n) and (o) about preservation lemmas and domain changes against the module.' },
  { key: 'closing', text: 'Section (q) (bilan de clôture du jalon 1) and its compliance with the brief, which asks each property to be classified as: proved on reached states; conditioned on a K contract (with the obligation); deferred (with destination: jalon 2, jalon 3, or call specification); safety counterexample still open (expected none). Check every theorem name and what it states (hypotheses: is it really on reached states? does it need DDSound?), whether any counterexample kept in the module (search for theorems with names containing fails, false, not_, cex, unexercisable, cycle) is a safety counterexample on reached states that (q) 4 misses, and whether J2-deferred items are classified as J2 says (quote the brief).' },
]
const results = await pipeline(PARTS,
  p => agent(`${COMMON}\n\nAssigned part: ${p.text}`, { label: `check:${p.key}`, phase: 'Check', schema: SCHEMA }),
  (r, p) => {
    const fs = (r && r.findings) || []
    if (!fs.length) return { part: p.key, findings: [], verdicts: [] }
    return agent(`${COMMON}\n\nYou are a skeptical judge. Below are findings another reviewer made about the report sections "${p.key}". For EACH finding, try hard to refute it: re-run the evidence yourself, read the cited module lines and the report text. real=true only if the report is actually wrong or the brief's requirement is actually unmet and you could not refute it. Default to real=false if uncertain. Index findings from 0.\n\nFindings:\n${JSON.stringify(fs, null, 1)}`,
      { label: `judge:${p.key}`, phase: 'Judge', schema: VERDICTS })
      .then(v => ({ part: p.key, findings: fs, verdicts: (v && v.verdicts) || [] }))
  })
return results.filter(Boolean).map(r => ({ part: r.part, confirmed: r.findings.map((f, i) => ({ ...f, verdict: (r.verdicts.find(v => v.index === i) || {}) })).filter(f => f.verdict.real), refuted: r.findings.map((f, i) => ({ claim: f.claim, verdict: (r.verdicts.find(v => v.index === i) || {}) })).filter(f => !f.verdict.real) }))

