export const meta = {
  name: 'mm23-report-verification',
  description: 'Verify the MM23 report claims against the module and specs, re-check review fixes, adversarially judge each finding',
  phases: [
    { title: 'Find', detail: 'four lenses over report and fixes' },
    { title: 'Judge', detail: 'one skeptic per finding' },
  ],
}

const SP = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad'
const COMMON = `You are a read-only verifier. Never modify files in the repository /Users/guygouri/Devlab/ernlang/ern. You may write scratch Lean files only under ${SP}/verif/ (create it) and check them with: cd /Users/guygouri/Devlab/ernlang/ern/formal && ~/.elan/bin/lake env lean <file> (start with "import Ern.MM23" then "open Ern.MM03 Ern.MM23"; the module is built). lake is not on PATH; use ~/.elan/bin/lake. There is no "timeout" command.
Files: module formal/Ern/MM23.lean (imports formal/Ern/MM02.lean and formal/Ern/MM03.lean, drafts left unchanged); report formal/reports/MM23_v0.1.md (French); task brief ${SP}/task_mm23_p1.md (arbitrages K1-K5 are normative); specs /Users/guygouri/Downloads/ERN_MM02_v04.md and /Users/guygouri/Downloads/ERN_MM-03.3_v0.3_revisee.md; project rules /Users/guygouri/Devlab/ernlang/ern/AGENTS.md. Git: branch formal/refinement_0.1; commits b8fd6fd..0dcbf43 are this pass (git log, git show are allowed).
Report only real problems backed by evidence: a command output, a Lean check, a quote of the report and of the code/spec it contradicts. A claim in the report counts as wrong if it is false, unverifiable from the module, overstated, or cites a declaration/witness that does not exist or does not show what is claimed. No evidence, no finding. Do not request additions beyond the task.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          severity: { type: 'string', enum: ['blocking', 'major', 'minor'] },
          location: { type: 'string' },
          claim: { type: 'string' },
          evidence: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['id', 'severity', 'location', 'claim', 'evidence', 'fix'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean' },
    reason: { type: 'string' },
    evidence: { type: 'string' },
  },
  required: ['real', 'reason', 'evidence'],
}

const LENSES = [
  { key: 'facts', prompt: `${COMMON}
Lens: the sections "État de vérification", "Résultats principaux", "(a) Clause → déclaration" and "(b) Statut" of the report. Check every factual statement: counts (theorems, examples, theorem constants: re-run "grep -c '^theorem' formal/Ern/MM23.lean", "grep -c '^example'", and the Lean script ${SP}/mm23/axcheck.lean), build cleanliness (run ~/.elan/bin/lake build in formal/), the forbidden-word grep, that MM02/MM03 are unchanged since 4e7cdbc, commit hashes, that every declaration named exists, that each theorem's hypotheses listed in (b) match its actual signature exactly (no hypothesis missing or invented), that each named witness exists and shows what is claimed (values, bases 16/28/40/52, tokens 101 and 7, allocations dead/live).` },
  { key: 'decisions', prompt: `${COMMON}
Lens: sections "(c) Décisions", "(d) Non prouvé" and "(e) Questions" of the report. For each item check: the description matches the code; any claim of necessity (e.g. "sans elle, r6_free est faux", "sous la lecture inverse, R6 serait faux", "K4 l'impose") is supported by a witness or a sound argument; witnesses cited (CaseOwnedLocal, Cases.af14, Cases.Lsh, Cases.e12b, CaseInit.cx, topPlacement_ok, placement_exists) show what is claimed; no decision is presented as dictated by a text when it is a choice; every choice not dictated by K1-K5 or the specs that the module makes is listed in (c) or (e) (look for silent choices in the module the report omits).` },
  { key: 'deviations', prompt: `${COMMON}
Lens: section "(f) Écarts" and section "Revue adverse" of the report. For each deviation claimed between the drafts (formal/Ern/MM03.lean, formal/Ern/MM02.lean) and their texts, check the quoted spec text exists and says that, the draft definition indeed differs, and the witness shows it. Then look for other deviations of the drafts from MM-03.3 v0.3 / MM-02 v0.4 that this pass ran into or relies on (definitions used by MM23: canRead3, canWrite3, WriteSharedPre, WF3, AllocStep, AllocStatic, FreePre, freeS, endUseS, enterEff, exitEff, ExitPre, S3.init, Read, CanWrite, CanDealloc, AllocPre, ReadStep, WriteStep, DeallocStep, AllocStep of MM02) and are missing from (f). Check that the "Revue adverse" section reports the reviewers' findings and their treatment accurately (the dispositions it claims exist in the module/report).` },
  { key: 'fixes', prompt: `${COMMON}
Lens: second targeted check of the review fixes in commit 0dcbf43 (git show 0dcbf43). Check: FreeSound was narrowed to the pair (p, auth) and r6_free became stronger, not weaker, and still means K4's "autorité Compatible issue de FreeCompat"; the new witnesses (CaseOwnedLocal, Cases.ao13/af14/La/na13/na14, Lsa, Lwi, m3x, the direct r1_read3 example) are reached states where claimed, prove what their docstrings say, and the clause-isolation tests really isolate K1 (a) and (c); the edited docstrings (Repr.leaked, exitOps) are accurate; no fix silently picks a semantic reading the report does not list, weakens a statement, or changes a verdict of an earlier case. Also re-run the build and the axiom script ${SP}/mm23/axcheck.lean.` },
]

phase('Find')
const results = await pipeline(
  LENSES,
  l => agent(l.prompt, { label: `find:${l.key}`, phase: 'Find', schema: FINDINGS }),
  (r, l) => parallel((r?.findings ?? []).map(f => () =>
    agent(`${COMMON}
A verifier reported the finding below about the MM23 report or module. Try to REFUTE it: re-check the evidence yourself (rerun commands, read the code and spec). It is real only if the report or module is actually wrong, overstated or unsupported as described. Default to real=false if you cannot confirm it.
Finding (${l.key}/${f.id}, ${f.severity}) at ${f.location}:
Claim: ${f.claim}
Evidence: ${f.evidence}
Proposed fix: ${f.fix}`, { label: `judge:${l.key}:${f.id}`, phase: 'Judge', schema: VERDICT })
      .then(v => ({ lens: l.key, ...f, verdict: v }))))
)
const all = results.flat().filter(Boolean)
const confirmed = all.filter(f => f.verdict?.real)
log(`${all.length} findings, ${confirmed.length} confirmed`)
return { confirmed, refuted: all.filter(f => !f.verdict?.real).map(f => ({ lens: f.lens, id: f.id, claim: f.claim, reason: f.verdict?.reason })) }

