  name: 'mm23-p2-second-check',
  description: 'Second targeted check of the MM23 pass-2 review fixes, report facts and completeness, with refutation',
  phases: [
    { title: 'Check', detail: 'fixes, report facts, completeness' },
    { title: 'Verify', detail: 'one refuter per lens with findings' },
