}

const SP = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad'

const COMMON = `You are an adversarial, read-only checker of a Lean 4 formalization (Lean core v4.35, no Mathlib).
Repository: /Users/guygouri/Devlab/ernlang/ern, branch formal/refinement_0.1, commit fe0bd8c. Module: formal/Ern/MM23.lean (refinement MM-03 -> MM-02). Report (in French): formal/reports/MM23_v0.1_p2.md.
History: pass 2 = commits 9c08116..fe0bd8c (pass 1 ended at cd079be). A first adversarial review ran on 579808d; its confirmed findings were fixed in fe0bd8c ("MM23 pass 2: review fixes and report"); the report's last section summarizes that review.
Task brief of this pass (arbitrages L1-L8, steps 1-6, deliverable (a)-(f)): ${SP}/task_mm23_p2.md. Pass-1 brief: ${SP}/task_mm23_p1.md. Normative specs: /Users/guygouri/Downloads/ERN_MM02_v04.md and /Users/guygouri/Downloads/ERN_MM-03.3_v0.3_revisee.md.
Follow the Review section of AGENTS.md. Do NOT modify any file in the repository. For experiments, write Lean files only under ${SP}/review2/<your lens>/ and check them with:
  cd /Users/guygouri/Devlab/ernlang/ern/formal && ~/.elan/bin/lake env lean <file>
with the header "import Ern.MM23" then "open Ern Ern.MM03 Ern.MM23". The build at fe0bd8c is up to date; do not run lake build. decide works on concrete states (namespaces Cases and CaseSim).
Every finding needs evidence: a quote, a Lean check you ran (file path and output), or command output. No evidence, no finding. A claim is supported only by a check that would fail if the claim were false. Do not ask for additions beyond the brief. Severity: blocking, major, minor.
Return only findings that survive your own check. An empty list is a valid answer.`

const LENSES = [
  { key: 'FIX', prompt: `Lens: the fixes of fe0bd8c (git diff 579808d fe0bd8c -- formal/Ern/MM23.lean). Check that each fix is correct and introduces no new problem:
- arenaProv, issueBytes, the new issueOps signature, assoc for issue, r6_issue, issue_prov_storage, pointer_sound_issue (new hypothesis ArenasInv and new conclusion): does each say what L6 says (provenance of issue = allocation of the arena storage), no stronger, no weaker? Is the added hypothesis ArenasInv justified (true on reached states: which MM03 theorem)? Does any fix silently pick a reading the brief leaves open, or change a verdict on a case the text is silent about (for example the empty block)?
- The rewritten docstrings (r6_transfer, simulation, regionAddr, pointer_sound_store, pointer_sound_issue, module header): does each now say exactly what its statement gives?
- The new CaseSim witnesses (empty region for issue and for store after split into [], region [6, 5] and layout Lsw, layout L0 of size 0): does each prove what its docstring claims, and is each reached state really reached?` },
  { key: 'FACTS', prompt: `Lens: the factual claims of the report formal/reports/MM23_v0.1_p2.md. For every factual claim (declaration names, statements and hypotheses attributed to theorems, counts: 178 theorems, 95 examples, 333 theorem constants; commit hashes and what each commit did; the witnesses cited and what they show; the numbering of the questions in (e) against the citations "pass-2 report, (e) N" in the module docstrings; the table in (f) against the actual statement of simulation and the premises of SimRun; the summary of the first review in the last section, against the journal of that review in /Users/guygouri/.claude/projects/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/subagents/workflows/wf_ad77d6e4-e1d/journal.jsonl), check it against the module or the git history. Report each claim that is false, overstated, or not supported by a module witness. Counts: count with a command and give it.` },
  { key: 'COMPL', prompt: `Lens: completeness against the brief. For each of L1-L8 and steps 1-6 of ${SP}/task_mm23_p2.md, list the declarations that formalize it and say whether anything the brief asks is missing. Check the deliverable: (a) clause -> declaration; (b) status of R1, R2, R4, R6 (full scope), ddSound_of_layout, pinned_address_stable, freeSound_derived, simulation; (c) decisions; (d) what is not proved; (e) questions; (f) the final list of simulation hypotheses, each classed spec 4 / spec 11 / bibliothèque / ouverte: is every hypothesis of simulation (its explicit arguments and the premises of SimRun and the envelope of Step3) in the list, with a class? Check that every rule-encoding definition or theorem added in pass 2 cites its clause or arbitrage. Report every rule left without a definition or theorem, and every deliverable item missing.` },
]

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          severity: { type: 'string', enum: ['blocking', 'major', 'minor'] },
          location: { type: 'string' },
          claim: { type: 'string' },
          evidence: { type: 'string' },
        },
        required: ['id', 'severity', 'location', 'claim', 'evidence'],
      },
    },
    checked: { type: 'string' },
  },
  required: ['findings', 'checked'],
}

const VERDICTS = {
  type: 'object',
  properties: {
    verdicts: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          real: { type: 'boolean' },
          severity: { type: 'string', enum: ['blocking', 'major', 'minor'] },
          reason: { type: 'string' },
          evidence: { type: 'string' },
        },
        required: ['id', 'real', 'severity', 'reason', 'evidence'],
      },
    },
  },
  required: ['verdicts'],
}

return await pipeline(
  LENSES,
  l => agent(`${COMMON}\n\n${l.prompt}\n\nUse ids ${l.key}-1, ${l.key}-2, ...`,
    { label: `check:${l.key}`, phase: 'Check', schema: FINDINGS }),
  (rev, l) => {
    if (!rev || rev.findings.length === 0) return { lens: l.key, review: rev, verdicts: [] }
    return agent(`${COMMON.replace('checker', 'verifier')}

A checker reported the findings below on the lens ${l.key}. For each one, try to REFUTE it: re-read the code, the report and the brief, rerun its check. Set real=false when the evidence does not hold up or the behaviour is what the brief asks; give your own severity when real.

Findings:
${JSON.stringify(rev.findings, null, 2)}`,
      { label: `verify:${l.key}`, phase: 'Verify', schema: VERDICTS })
      .then(v => ({ lens: l.key, review: rev, verdicts: v ? v.verdicts : null }))
  },
)

