export const meta = {
  name: 'j3-second-check',
  description: 'Second targeted check of the jalon-3 review fixes and report, with adversarial verification of each finding',
  phases: [
    { title: 'Check', detail: 'four independent checkers over report, MM23-H fixes, MM3-H/LockOptions fixes, brief coverage' },
    { title: 'Verify', detail: 'one refuter per finding' },
  ],
}

const COMMON = `You are a read-only adversarial checker (apply the "Review (Codex)" section of /Users/guygouri/Devlab/ernlang/ern/AGENTS.md). Do NOT edit any repository file. Scratch Lean files go in a fresh dir from \`mktemp -d\`; check them with \`cd /Users/guygouri/Devlab/ernlang/ern/formal && ~/.elan/bin/lake env lean /path/file.lean\` (modules are built; useful imports: \`import Ern.MM03.LockOptions\`, \`import Ern.MM23.Horrors\`; opens: \`open Ern Ern.MM03 Ern.HandlePool Ern.MM03.Horrors Ern.MM03.LockOptions Ern.MM23 Ern.MM23.Horrors\`). Sources: material /Users/guygouri/Downloads/ERN_Jalon3_materiel.md (cases §1, §3, §5b; pool contract §4; NoLock §5; rules §0), spec /Users/guygouri/Downloads/ERN_MM-03.3_v0.3_revisee.md. Modules: formal/Ern/HandlePool.lean, formal/Ern/MM03/Horrors.lean, formal/Ern/MM23/Horrors.lean, formal/Ern/MM03/LockOptions.lean. Report: formal/reports/J3_v0.1.md (French). The last commit (6cb3f1b) applied fixes after a first review; \`git -C /Users/guygouri/Devlab/ernlang/ern show 6cb3f1b --stat\` and \`git show 6cb3f1b\` show them. Every finding needs evidence: a quote, a decided Lean statement, or command output. No evidence, no finding. Do not ask for additions beyond the task. Report only real defects (wrong claim, statement weaker than its source, missing coverage the brief demands, a fix that introduced an error); return an empty list if none.`

const BRIEF = `The task brief (jalon 3), summarized: step 1 HandlePool per material §4 (pool entry state, fresh identity, newPool/allocSlot/resolve/resolveMany/unresolve/freeSlot built on derive/split/release/endUse without changing them; PoolInv; Reachable extension in the module; the theorems of §4; pool_resolve_modify_exclusive on every reached state whatever the sequence of resolve, resolveMany, release, store, transfer, unresolve). Step 2: MM3-H all rows of sections A–I plus W1–W3 in Ern/MM03/Horrors.lean; each case: state reached from the initial state, expected verdict per its source, positive twin for each rejection, class; covered cases replayed from the initial state; section J not encoded, confirm none expressible or signal the one that is. Step 3: MM23-H each case as an execution translated by simulation; H15 and H16 encoded with the obtained verdict and marked "écart connu" (rule 8); H14 and H17 not encoded, classified. Step 4: NoLock measure in Ern/MM03/LockOptions.lean without modifying the kernel: option 2 self-lock predicate for transfer and issue; option 3 relation "b blocks a" (b ≠ a, both active, footprint of b contains a leaf of the holder of a), self-lock as a separate clause, acyclicity predicate; for each must-accept case (H11, H19, H29b, H35–H37, H44–H47, W1–W3) and H49–H51 the decision of each option by decide on the state and step concerned; cost: whether each option is checked from only the authorities and places touched by the operation or needs to scan the whole state, a locality lemma if so, a counterexample otherwise; no option adopted. Rules: zero sorry; axioms at most propext, Quot.sound on all constants of the new modules; no noncomputable; build without warning; docstrings cite clause, arbitrage or case id; nothing invented; no statement weakened; an obtained verdict differing from the expected one is never corrected or worked around; adversarial review centred on pool_resolve_modify_exclusive, twins, and the NoLock measure; counterexamples kept. Deliverable: modules committed; formal/reports/J3_v0.1.md in French with (a) table case → example, expected, obtained, source, class, twin; (b) deviations expected vs obtained, each with the state and step at fault; (c) known deviations (rule 8); (d) status of HandlePool theorems; (e) NoLock table: per option, false rejections, residual blockings on H49–H51, locality; (f) decisions not dictated by the material; (g) questions for arbitration. Code, docstrings, comments, commits in English; report in French. MM02.lean, MM03.lean, MM23.lean unchanged.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          severity: { type: 'string', enum: ['blocking', 'major', 'minor'] },
          location: { type: 'string' },
          claim: { type: 'string', description: 'the defect, one or two sentences' },
          evidence: { type: 'string', description: 'quote, decided Lean statement or command output' },
          fix: { type: 'string', description: 'the smallest correction' },
        },
        required: ['severity', 'location', 'claim', 'evidence', 'fix'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean', description: 'true if the finding is a real defect after your own check' },
    reason: { type: 'string' },
    evidence: { type: 'string' },
  },
  required: ['real', 'reason', 'evidence'],
}

const CHECKERS = [
  { key: 'report-facts', prompt: `${COMMON}\n\nLens: fact-check the report formal/reports/J3_v0.1.md against the modules. For every Lean name it cites, check the constant exists (grep or #check) and states what the report says; check every verdict in tables (a) and (e), every count (constants, theorems, steps per case, 51/54 cases), every claim in (b)–(g) and in the "Revue adverse" section. Check French phrasing only where it changes meaning. A claim without a module witness is a finding.` },
  { key: 'mm23-fixes', prompt: `${COMMON}\n\nLens: the MM23-H fixes in formal/Ern/MM23/Horrors.lean (step_ok_of, srun_append, sexec_step, H02 and reset_kills_blocks_after, H04, H05, H06, H07 with the KNS instances and r7n, H07_ok, H09, H10). Check each statement against the material §3 "Attendu" (not weaker, about the right step), that step_ok_of really proves the step's MM-02 sequence ok in the state where it runs, that the KNS instances agree with KNS's fields (MM03.lean, def KNS), and that no fix introduced an unsound or vacuous statement.` },
  { key: 'mm03-lock-fixes', prompt: `${COMMON}\n\nLens: the fixes in formal/Ern/MM03/Horrors.lean (H01_reborrow, H03, H07, H17 and KF45, H22, H51, W2, W3 and the new w3vo, and the new section "Observations on the contract of the pool": pool_freeSlot_derived_internal, pool_freeSlot_shared_right, pool_two_on_one_internal, pool_two_freeSlot_cross, arena_on_pool_internal, pool_free_entry_handle, pool_allocSlot_content_init) and in formal/Ern/MM03/LockOptions.lean (module docstring, mustAccept W3v, opt2/opt3_decisions, H49_options, H51_options, nl1/nl2, opt3_not_local). Check twins are minimal (same run without the faulty element), docstrings name the true failing clause (evaluate clauses on the states), the W3 variant follows the material's W3 sequence, opt3_not_local's states are kernel-ok for the step and differ as claimed, and the new witnesses say what the report (g) says they say.` },
  { key: 'brief-coverage', prompt: `${COMMON}\n\n${BRIEF}\n\nLens: completeness against the brief. Check every requirement of the brief is met or explicitly reported: each step's content, each report section's required columns (e.g. (b) must give state and step for each deviation; (a) must have source, class, twin for every case), section J handling, H14/H17 classification, rule 8 marking, "un verdict obtenu différent de l'attendu n'est jamais corrigé ni contourné" (look for any case whose construction was changed to obtain the expected verdict without the deviation being reported), and that MM02.lean, MM03.lean, MM23.lean are unchanged since the branch point (\`git -C /Users/guygouri/Devlab/ernlang/ern diff formal/refinement_0.1 -- formal/Ern/MM02.lean formal/Ern/MM03.lean formal/Ern/MM23.lean\`). Run \`cd /Users/guygouri/Devlab/ernlang/ern/formal && ~/.elan/bin/lake build 2>&1 | tail -3\` and the grep \`grep -rnE '\\b(sorry|admit|native_decide)\\b|^\\s*axiom\\b' --include='*.lean' --exclude-dir=.lake /Users/guygouri/Devlab/ernlang/ern\`.` },
]

const results = await pipeline(
  CHECKERS,
  c => agent(c.prompt, { label: `check:${c.key}`, phase: 'Check', schema: FINDINGS }),
  (res, c) => parallel((res && res.findings ? res.findings : []).map((f, i) => () =>
    agent(`${COMMON}\n\nAnother checker reported the finding below. Try to REFUTE it by your own check (re-run the evidence, read the source passages, evaluate in Lean). Default to real=false if the evidence does not hold up or the claim misreads the material, the brief or the module.\n\nFinding (${f.severity}) at ${f.location}:\n${f.claim}\nEvidence given: ${f.evidence}\nProposed fix: ${f.fix}`,
      { label: `verify:${c.key}:${i}`, phase: 'Verify', schema: VERDICT })
      .then(v => ({ ...f, lens: c.key, verdict: v })))),
)
const all = results.flat().filter(Boolean)
const confirmed = all.filter(f => f.verdict && f.verdict.real)
const refuted = all.filter(f => !(f.verdict && f.verdict.real))
log(`${all.length} findings, ${confirmed.length} confirmed, ${refuted.length} refuted`)
return { confirmed, refuted: refuted.map(f => ({ lens: f.lens, location: f.location, claim: f.claim, reason: f.verdict ? f.verdict.reason : 'no verdict' })) }

